import gurobipy as gp
from gurobipy import GRB

# Create model with environment
env = gp.Env.defaultEnvironment()
model = gp.Model(env=env)

# Parameters
cycle_time = 66
num_tasks = 10

# Task durations
task_durations = {
    1: 36, 2: 36, 3: 30, 4: 30, 5: 24,
    6: 30, 7: 24, 8: 12, 9: 54, 10: 12
}

# Predecessors for each task
predecessors = {
    1: [], 2: [1], 3: [], 4: [3], 5: [1, 4],
    6: [5], 7: [2], 8: [6, 7], 9: [8], 10: [9]
}

# Calculate upper bound on workstations
total_duration = sum(task_durations.values())
max_workstations = total_duration // cycle_time + 2

# Decision variables
# x[i][j] = 1 if task i is assigned to workstation j
x = {}
for i in range(1, num_tasks + 1):
    for j in range(1, max_workstations + 1):
        x[(i, j)] = model.addVar(vtype=GRB.BINARY, name=f"x_{i}_{j}")

# Objective: minimize number of workstations used
# We'll minimize the maximum workstation index that has any task assigned
# Use a binary variable for each workstation being used
ws_used = {}
for j in range(1, max_workstations + 1):
    ws_used[j] = model.addVar(vtype=GRB.BINARY, name=f"ws_used_{j}")

# Constraint: each task assigned to exactly one workstation
for i in range(1, num_tasks + 1):
    model.addConstr(
        gp.quicksum(x[(i, j)] for j in range(1, max_workstations + 1)) == 1,
        name=f"assign_{i}"
    )

# Constraint: total duration at each workstation ≤ cycle time
for j in range(1, max_workstations + 1):
    model.addConstr(
        gp.quicksum(task_durations[i] * x[(i, j)] for i in range(1, num_tasks + 1)) <= cycle_time,
        name=f"duration_{j}"
    )

# Constraint: precedence relationships
# If task i is assigned to workstation j, all predecessors must be assigned to workstation k ≤ j
for i in range(1, num_tasks + 1):
    for pred in predecessors[i]:
        for j in range(1, max_workstations + 1):
            model.addConstr(
                x[(i, j)] <= gp.quicksum(x[(pred, k)] for k in range(1, j + 1)),
                name=f"precedence_{pred}_{i}_{j}"
            )

# Constraint: link task assignments to workstation usage
for j in range(1, max_workstations + 1):
    model.addConstr(
        gp.quicksum(x[(i, j)] for i in range(1, num_tasks + 1)) <= ws_used[j] * max_workstations,
        name=f"ws_usage_{j}"
    )

# Objective: minimize number of workstations used
model.setObjective(
    gp.quicksum(ws_used[j] for j in range(1, max_workstations + 1)),
    GRB.MINIMIZE
)

# Optimize
model.optimize()

# Get result
if model.status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.objVal}")

