from gurobipy import GRB

# Create model
model = gp.Model()

# Define products
products = ['A', 'B', 'C', 'D', 'E']

# Define arcs with capacity and cost
arcs = {
    (1, 2): (20, 3),
    (1, 3): (15, 4),
    (2, 3): (10, 2),
    (2, 4): (12, 5),
    (3, 5): (18, 3),
    (3, 6): (10, 6),
    (4, 5): (8, 1),
    (5, 6): (15, 2)
}

# Create decision variables for each arc and product
x = {}
for (i, j), (cap, cost) in arcs.items():
    for p in products:
        x[(i, j, p)] = model.addVar(lb=0, ub=cap, name=f"x_{i}_{j}_{p}")

# Set objective: minimize total transportation cost
model.setObjective(gp.quicksum(arcs[(i, j)][1] * x[(i, j, p)] 
                               for (i, j), (cap, cost) in arcs.items() 
