dependencies = {'C': 'A', 'E': 'D', 'G': 'B', 'I': 'H', 'J': 'G'}
berths = ['B1', 'B2', 'B3']
time_horizon = 72

# Decision variables
berth_assign = {}
start_time = {}
bonus = {}

for ship in ships:
    for b in berths:
        berth_assign[(ship, b)] = model.addVar(vtype=GRB.BINARY, name=f"berth_{ship}_{b}")
    start_time[ship] = model.addVar(lb=arrival_times[ship], name=f"start_{ship}")
    bonus[ship] = model.addVar(vtype=GRB.BINARY, name=f"bonus_{ship}")

# Each ship assigned to exactly one berth
for ship in ships:
    model.addConstr(gp.quicksum(berth_assign[(ship, b)] for b in berths) == 1, name=f"assign_{ship}")

# Berth capacity constraints using big-M
M = 1000
for b in berths:
    for i, ship_i in enumerate(ships):
        for j, ship_j in enumerate(ships):
            if i < j:
                model.addConstr(
                    berth_assign[(ship_i, b)] + berth_assign[(ship_j, b)] <= 1,
                    name=f"berth_{b}_{ship_i}_{ship_j}"
                )

# Dependency constraints: successor must start after predecessor completes
for ship, pred in dependencies.items():
    model.addConstr(
        start_time[ship] >= start_time[pred] + durations[pred],
        name=f"dep_{ship}_{pred}"
    )

# Rapid transshipment bonus constraints
# Bonus applies if start_time[ship] <= end_time[pred] + 2
for ship, pred in dependencies.items():
    model.addConstr(
        bonus[ship] <= 1,
        name=f"bonus_upper_{ship}"
    )
    model.addConstr(
        bonus[ship] <= 1,
        name=f"bonus_lower_{ship}"
    )

# Objective: maximize bonus - waiting cost
model.setObjective(
    gp.quicksum(50000 * bonus[ship] - 2000 * (start_time[ship] - arrival_times[ship]) for ship in ships),
    GRB.MAXIMIZE
)

model.optimize()

if model.Status == GRB.OPTIMAL:
    print(f"FINAL_OBJECTIVE={model.ObjVal:.17g}")
